import type { LucideIcon } from 'lucide-react';
import type { Href } from '@/lib/navigation';
import { toUrl } from '@/lib/navigation';

export type NavItem = {
    title: string;
    href: Href;
    icon?: LucideIcon;
    tour?: string;
    goKey?: string;
};

export type GatedItem = NavItem & {
    permission?: string;
    anyPermission?: string[];
};

export type NavGroup = {
    label?: string;
    items: GatedItem[];
};

export type GoShortcut = {
    key: string;
    title: string;
    url: string;
};

export const canSee = (
    item: Pick<GatedItem, 'permission' | 'anyPermission'>,
    granted: string[],
): boolean =>
    (!item.permission || granted.includes(item.permission)) &&
    (!item.anyPermission ||
        item.anyPermission.some((permission) => granted.includes(permission)));

export const visibleGroups = (groups: NavGroup[], granted: string[]): NavGroup[] =>
    groups
        .map((group) => ({
            ...group,
            items: group.items.filter((item) => canSee(item, granted)),
        }))
        .filter((group) => group.items.length > 0);

export const permissionsIn = (groups: NavGroup[]): string[] =>
    groups.flatMap((group) =>
        group.items.flatMap((item) => (item.permission ? [item.permission] : [])),
    );

export const goShortcuts = (groups: NavGroup[], granted: string[]): GoShortcut[] =>
    visibleGroups(groups, granted)
        .flatMap((group) => group.items)
        .flatMap((item) =>
            item.goKey ? [{ key: item.goKey, title: item.title, url: toUrl(item.href) }] : [],
        );

import { useCurrentUrl } from '@/lib/navigation';

const base = 'http://localhost';

const matchScore = (href: string, current: URL): number => {
    const target = new URL(href, base);
    const path = target.pathname.replace(/\/$/, '');
    const params = [...target.searchParams];
    const onPath =
        current.pathname === target.pathname ||
        current.pathname.startsWith(`${path}/`);
    const onQuery = params.every(
        ([key, value]) => current.searchParams.get(key) === value,
    );

    return onPath && onQuery ? path.length * 100 + params.length : -1;
};

export function useActiveNavHref(hrefs: string[]): string | null {
    const current = new URL(useCurrentUrl(), base);

    return hrefs.reduce<{ href: string | null; score: number }>(
        (best, href) => {
            const score = matchScore(href, current);

            return score > best.score ? { href, score } : best;
        },
        { href: null, score: -1 },
    ).href;
}
